# Generated by Phase: IMPLEMENT | Feature: EVOL-043
"""Shared primitives of the gates package: repo root, context, config, frontmatter, globs.

One reader for every gate key (`config/quality.json`), one frontmatter parser for the Python gates
(shell hooks keep awk for hash lookups), one glob matcher. Stdlib only; PyYAML when present, a strict
subset parser otherwise.
"""
from __future__ import annotations

import fnmatch
import json
import os
import re
import subprocess
from pathlib import Path

QUALITY = "config/quality.json"
COHERENCE = "config/coherence-context.json"


class GateFault(Exception):
    """The gate cannot do its job (missing config, unreadable input). Plain language (LAW-08)."""


# ─── repo + context ─────────────────────────────────────────────────────────────

def repo_root(start: Path | None = None) -> Path:
    env = os.environ.get("CLAUDE_PROJECT_DIR")
    if env and Path(env).is_dir():
        return Path(env).resolve()
    try:
        out = subprocess.run(["git", "rev-parse", "--show-toplevel"], cwd=str(start or Path.cwd()),
                             capture_output=True, text=True, timeout=20)
        if out.returncode == 0 and out.stdout.strip():
            return Path(out.stdout.strip()).resolve()
    except (OSError, subprocess.TimeoutExpired):
        pass
    return (start or Path.cwd()).resolve()


def _load_json(repo: Path, rel: str, strict: bool) -> dict:
    """A config file: {} when absent; unreadable JSON is a GateFault when strict (a corrupt config must
    never silently change what a gate does)."""
    p = repo / rel
    if not p.is_file():
        return {}
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as e:
        if strict:
            raise GateFault(f"{rel} is not readable JSON ({e}); fix it before any gate can run") from None
        return {}
    return data if isinstance(data, dict) else {}


def load_quality(repo: Path) -> dict:
    return _load_json(repo, QUALITY, strict=True)


def load_coherence(repo: Path) -> dict:
    return _load_json(repo, COHERENCE, strict=True)


def context(repo: Path) -> str:
    """`meta` (framework repo) or `downstream` (materialised project). Declared in coherence-context.json;
    falls back to the presence of the template tree."""
    declared = load_coherence(repo).get("context")
    if declared in ("meta", "downstream"):
        return declared
    return "meta" if (repo / ".context/templates/setup").is_dir() else "downstream"


def rules_root(repo: Path) -> Path:
    return repo / (".context/templates/setup/rules" if context(repo) == "meta" else ".claude/rules")


def constitution_path(repo: Path) -> Path | None:
    """The project law index: docs/constitution.md downstream; the template in meta. None when absent."""
    p = repo / (".context/templates/setup/constitution/constitution_template.md" if context(repo) == "meta"
                else "docs/constitution.md")
    return p if p.is_file() else None


def resolve_pointer(repo: Path, pointer: str) -> Path | None:
    """Body pointer → file. `rules/x.md` resolves against the rules root; other forms are repo-relative;
    the literal `inline` → None."""
    pointer = pointer.strip().strip("`")
    if pointer == "inline":
        return None
    if pointer.startswith("rules/"):
        return rules_root(repo) / pointer[len("rules/"):]
    return repo / pointer


def key(repo: Path, dotted: str, default=None, required: bool = False):
    """Read `a.b.c` from config/quality.json. `required=True` fails closed on a missing key."""
    node = load_quality(repo)
    for part in dotted.split("."):
        node = node.get(part) if isinstance(node, dict) else None
        if node is None:
            break
    if node is None:
        if required:
            raise GateFault(f"config key `{dotted}` is missing from {QUALITY} — every threshold is a key, never a digit in prose")
        return default
    return node


# ─── frontmatter ────────────────────────────────────────────────────────────────

FM_RE = re.compile(r"\A---\r?\n(.*?)\r?\n---\r?\n", re.DOTALL)


def _indent(line: str) -> int:
    return len(line) - len(line.lstrip(" "))


def _split_inline(s: str) -> list[str]:
    out, cur, quote = [], "", None
    for ch in s:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
            cur += ch
        elif ch == ",":
            out.append(cur)
            cur = ""
        else:
            cur += ch
    if cur.strip():
        out.append(cur)
    return [x.strip() for x in out]


def _scalar(v: str):
    v = v.strip()
    if v.startswith("[") and v.endswith("]"):
        inner = v[1:-1].strip()
        return [_scalar(x) for x in _split_inline(inner)] if inner else []
    if v in ("true", "True"):
        return True
    if v in ("false", "False"):
        return False
    if v in ("null", "~", ""):
        return None
    if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
        return v[1:-1]
    if re.fullmatch(r"-?\d+", v):
        return int(v)
    return v


def _mini_yaml(text: str):
    """Strict subset: mappings by 2-space indent, `- item` lists, inline `[a, b]`, scalars. Enough for the
    frontmatter this framework writes. Anything else → GateFault (install PyYAML for full YAML)."""
    lines = [ln.rstrip("\n") for ln in text.splitlines() if ln.strip() and not ln.strip().startswith("#")]

    def parse_block(i: int, indent: int):
        if i < len(lines) and lines[i].lstrip().startswith("- "):
            items = []
            while i < len(lines) and _indent(lines[i]) == indent and lines[i].lstrip().startswith("- "):
                items.append(_scalar(lines[i].lstrip()[2:]))
                i += 1
            return items, i
        mapping: dict = {}
        while i < len(lines):
            ind = _indent(lines[i])
            if ind < indent:
                break
            if ind > indent:
                raise GateFault(f"frontmatter subset parser: unexpected indent at `{lines[i].strip()}`")
            body = lines[i].strip()
            if ":" not in body:
                raise GateFault(f"frontmatter subset parser: expected `key: value`, got `{body}`")
            k, _, v = body.partition(":")
            i += 1
            if v.strip() in ("", "|", ">"):
                if i < len(lines) and _indent(lines[i]) > indent:
                    child, i = parse_block(i, _indent(lines[i]))
                    mapping[k.strip()] = child
                else:
                    mapping[k.strip()] = None
            else:
                mapping[k.strip()] = _scalar(v)
        return mapping, i

    data, _ = parse_block(0, _indent(lines[0]) if lines else 0)
    return data


def parse_yaml(text: str):
    try:
        import yaml  # type: ignore
        return yaml.safe_load(text) or {}
    except ImportError:
        return _mini_yaml(text)
    except Exception as e:  # yaml.YAMLError
        raise GateFault(f"frontmatter is not valid YAML: {e}") from None


def read_frontmatter(path: Path) -> dict:
    """The one frontmatter parser of the Python gates. Returns {} when the file has none."""
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as e:
        raise GateFault(f"cannot read {path}: {e}") from None
    m = FM_RE.match(text)
    if not m:
        return {}
    data = parse_yaml(m.group(1))
    return data if isinstance(data, dict) else {}


def body_after_frontmatter(text: str) -> str:
    m = FM_RE.match(text)
    return text[m.end():] if m else text


# ─── globs ──────────────────────────────────────────────────────────────────────

def _glob_regex(pattern: str) -> str:
    out, i = "", 0
    while i < len(pattern):
        ch = pattern[i]
        if pattern.startswith("**/", i):
            out += "(?:.*/)?"
            i += 3
        elif pattern.startswith("**", i):
            out += ".*"
            i += 2
        elif ch == "*":
            out += "[^/]*"
            i += 1
        elif ch == "?":
            out += "[^/]"
            i += 1
        elif ch == "{":
            j = pattern.find("}", i)
            if j == -1:
                out += re.escape(ch)
                i += 1
            else:
                out += "(?:" + "|".join(_glob_regex(a) for a in pattern[i + 1:j].split(",")) + ")"
                i = j + 1
        else:
            out += re.escape(ch)
            i += 1
    return out


def glob_match(path: str, pattern: str) -> bool:
    """`**` crosses separators, `*` stays in a segment, `{a,b}` alternates, a bare directory prefix (`src/`)
    matches below it. A pattern without a leading `**/` still matches at any depth. Dot-prefixed paths
    (`.github/…`) are ordinary paths — only a literal `./` prefix is removed."""
    path = path.replace("\\", "/")
    while path.startswith("./"):
        path = path[2:]
    pattern = pattern.strip().replace("\\", "/")
    if pattern in ("*", "**", "**/*"):
        return True
    if pattern.endswith("/"):
        return path.startswith(pattern) or path == pattern.rstrip("/")
    return re.fullmatch(_glob_regex("**/" + pattern), path) is not None


def any_glob(path: str, patterns) -> bool:
    return any(glob_match(path, p) for p in (patterns or []))


def tracked_files(repo: Path) -> list[str]:
    try:
        out = subprocess.run(["git", "-C", str(repo), "ls-files"], capture_output=True, text=True, timeout=60)
        if out.returncode == 0:
            return [ln for ln in out.stdout.splitlines() if ln]
    except (OSError, subprocess.TimeoutExpired):
        pass
    return [str(p.relative_to(repo)) for p in repo.rglob("*") if p.is_file() and ".git" not in p.parts]


def fnmatch_any(name: str, patterns) -> bool:
    return any(fnmatch.fnmatch(name, p) for p in (patterns or []))
